/** The tables of fixture-agents-db and the clauses their statements are written with. */
export const fixtureAgentsDbOrm: OrmDefinition = {
  clauses: {
    eq: "%s = $%d",
    gt: "%s > $%d",
    gte: "%s >= $%d",
    lt: "%s < $%d",
    lte: "%s <= $%d",
    ilike: "%s ILIKE $%d",
    in: "%s IN (%s)",
    isNull: "%s IS NULL",
    isNotNull: "%s IS NOT NULL",
    search: "%s ILIKE $%d ESCAPE '\\'",
    exists: "EXISTS (%s)",
    notExists: "NOT EXISTS (%s)",
    set: "%s = $%d",
    setNull: "%s = NULL",
    pageKey: "page_key.%s",
    placeholder: "$%d",
    default: "DEFAULT",
    or: " OR ",
    group: "(%s)",
    where: " WHERE ",
    and: " AND ",
    orderBy: " ORDER BY ",
    orderTerm: "%s %s",
    limit: " LIMIT %d",
    offset: " OFFSET %d",
    setExcluded: "%s = EXCLUDED.%s",
    excluded: "EXCLUDED.%s",
    changed: "(%s) IS DISTINCT FROM (%s)",
    never: "FALSE",
    null: "NULL",
    notIn: "%s NOT IN (%s)",
  },
  defaultLimit: 100,
  manyLimit: 1000000,
  historyActorCTE: "WITH history_actor AS MATERIALIZED (\n\tSELECT set_config('superschematic.history_actor_id', COALESCE($1::text, ''), true) AS _history_actor\n)\n",
  clearHistoryActor: "SELECT set_config('superschematic.history_actor_id', '', true)",
  tables: {
    account: accountTable,
    job: jobTable,
    session: sessionTable,
    workspace: workspaceTable,
  },
  rules: fixtureAgentsDbRules,
};

/**
 * Opens the repositories of fixture-agents-db over pool, acting as the user
 * options names, or as the user it is when a string. The behaviors'
 * core is options.rules, or the rules package's, made when a behavior first
 * runs.
 */
export function createOrm(pool: OrmPool, options?: string | null | OrmOptions): FixtureAgentsDbOrm {
  return ormOf<FixtureAgentsDbRepositories>(pool, fixtureAgentsDbOrm, withRulesCore(options, initSync));
}
